  "skill": "deploy_service",
  "notes": "Contract synthesized from refusal observations: operation is refused when unauthenticated, deployment is not idle, cluster tier is missing/unsupported, or target region is missing/unserviceable. All state variables are unchanged on refusal.",
  "precondition": {
    "op": "or",
    "args": [
      {
        "op": "not",
        "arg": {
          "op": "is_true",
          "arg": {
            "var": "authenticated",
            "when": "before"
          }
        }
      },
      {
        "op": "eq",
        "left": {
          "var": "deployment_status",
          "when": "before"
        },
        "right": {
          "const": "deployed"
        }
      },
      {
        "op": "eq",
        "left": {
          "var": "deployment_status",
          "when": "before"
        },
        "right": {
          "const": "stopped"
        }
      },
      {
        "op": "eq",
        "left": {
          "var": "deployment_status",
          "when": "before"
        },
        "right": {
          "const": "rolledback"
        }
      },
      {
        "op": "is_null",
        "arg": {
          "var": "cluster_tier",
          "when": "before"
        }
      },
      {
        "op": "in_set",
        "value": {
          "var": "cluster_tier",
          "when": "before"
        },
        "set": "rejected_cluster_tiers"
      },
      {
        "op": "is_null",
        "arg": {
          "var": "target_region",
          "when": "before"
        }
      },
      {
        "op": "in_set",
        "value": {
          "var": "target_region",
          "when": "before"
        },
        "set": "rejected_regions"
      }
    ]
  },
  "postcondition": {
    "op": "unchanged",
    "vars": [
      "active_deployment",
      "active_size",
      "allocated_resources",
      "allocation_size",
      "authenticated",
      "available_quota",
      "allocation_size",
      "cluster_tier",
      "deployment_status",
      "quota_size",
      "target_region"
    ]
  }
}
